import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.DncwoWA8.js";const r="/projects/ai-skills/diagrams/required-dependencies.svg",m=JSON.parse('{"title":"Requirements, companions, and handoffs","description":"","frontmatter":{"title":"Requirements, companions, and handoffs"},"headers":[],"relativePath":"reference/relationships.md","filePath":"reference/relationships.md"}'),n={name:"reference/relationships.md"};function o(l,e,d,c,p,h){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="requirements-companions-and-handoffs" tabindex="-1">Requirements, companions, and handoffs <a class="header-anchor" href="#requirements-companions-and-handoffs" aria-label="Permalink to &quot;Requirements, companions, and handoffs&quot;">​</a></h1><p>A line between two skill names can mean different things. Treating every useful combination as a prerequisite produces unnecessary installations and unsafe automatic follow-up work.</p><h2 id="required-instruction-dependencies" tabindex="-1">Required instruction dependencies <a class="header-anchor" href="#required-instruction-dependencies" aria-label="Permalink to &quot;Required instruction dependencies&quot;">​</a></h2><p><code>A → B</code> in this map means: resolve the installed instructions for <strong>B before applying A</strong>. It does not mean execute B after A. The catalog currently records <strong>6 edges</strong>, checked against the local <code>requires</code> frontmatter.</p><p><img src="'+r+'" alt="Six declared instruction dependencies, directed from each requesting skill to its required instructions."></p><p><a href="/projects/ai-skills/diagrams/required-dependencies.html">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/required-dependencies.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/required-dependencies.json">Editable candidate</a></p><table tabindex="0"><thead><tr><th>Requesting skill</th><th>Required instructions</th></tr></thead><tbody><tr><td><a href="/projects/ai-skills/skills/cleanup-workspaces.html"><code>cleanup-workspaces</code></a></td><td><a href="/projects/ai-skills/skills/isolated-workspace.html"><code>isolated-workspace</code></a></td></tr><tr><td><a href="/projects/ai-skills/skills/coding-with-rules.html"><code>coding-with-rules</code></a></td><td><a href="/projects/ai-skills/skills/coding.html"><code>coding</code></a></td></tr><tr><td><a href="/projects/ai-skills/skills/grill-me.html"><code>grill-me</code></a></td><td><a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a></td></tr><tr><td><a href="/projects/ai-skills/skills/initiative.html"><code>initiative</code></a></td><td><a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a></td></tr><tr><td><a href="/projects/ai-skills/skills/research.html"><code>research</code></a></td><td><a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a></td></tr><tr><td><a href="/projects/ai-skills/skills/specify.html"><code>specify</code></a></td><td><a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a></td></tr></tbody></table><p>The <code>requires</code> declaration is a project extension, not a standard Agent Skills field or a native loader guarantee. Resolve recursively in array order, stop on missing requirements or cycles, and obtain approved setup. Direct Skills CLI installation does not automatically install this closure. The manager&#39;s reviewed selection handles catalogued prerequisites.</p><h2 id="installation-prerequisites" tabindex="-1">Installation prerequisites <a class="header-anchor" href="#installation-prerequisites" aria-label="Permalink to &quot;Installation prerequisites&quot;">​</a></h2><p>These are things that must exist before installation or use: an approved source, a trusted checkout, a parser dependency, filesystem support, or other documented setup. Do not turn a tool prerequisite into a new skill dependency. Installation still needs applicable approval.</p><h2 id="runtime-and-harness-requirements" tabindex="-1">Runtime and harness requirements <a class="header-anchor" href="#runtime-and-harness-requirements" aria-label="Permalink to &quot;Runtime and harness requirements&quot;">​</a></h2><p>A skill can need Bun, Node.js, a local browser, a rendering CLI, or authorized subagent tools without requiring another skill. The profile&#39;s runtime section comes from the catalog; the linked authoritative instructions define the complete contract. A supported harness name does not prove those capabilities are present.</p><h2 id="optional-companions" tabindex="-1">Optional companions <a class="header-anchor" href="#optional-companions" aria-label="Permalink to &quot;Optional companions&quot;">​</a></h2><p>A companion helps under a stated condition. For example, choose <code>tdd</code> when the owner wants test-first work, or a diagram skill when the reader needs a visual relationship explanation. Do not install or run every companion automatically.</p><h2 id="phase-handoffs-and-owner-decisions" tabindex="-1">Phase handoffs and owner decisions <a class="header-anchor" href="#phase-handoffs-and-owner-decisions" aria-label="Permalink to &quot;Phase handoffs and owner decisions&quot;">​</a></h2><p>A workflow arrow suggests a later phase; it is not a new <code>requires</code> edge or permission to continue. Research can end at findings, planning at a task list, scaffolding at a skeleton, and review at findings. Approval gates remain on the operation they protect. A draft cannot approve itself, and a successful review cannot authorize a merge or release.</p><p><a href="/projects/ai-skills/workflows/">Choose a workflow</a> or <a href="/projects/ai-skills/skills/">inspect an individual skill</a>.</p>',17)])])}const f=a(n,[["render",o]]);export{m as __pageData,f as default};
